    anchorType: "$ConceptType",
    anchorName: "Preference",
    source: "// --- DEFINE the \"Preference\" concept type and \"prefers\" predicate ---\nUPSERT {\n    CONCEPT ?preference_type_def {\n        {type: \"$ConceptType\", name: \"Preference\"}\n        SET ATTRIBUTES {\n            description: \"Represents a first-class stable preference fact in the graph: some subject reliably prefers something. Use `Preference` when the preference should be queryable, shareable, supported by evidence across Events, or evolve over time.\",\n            display_hint: \"⭐\",\n            instance_schema: {\n                \"description\": {\n                    \"type\": \"string\",\n                    \"is_required\": true,\n                    \"description\": \"A concise statement of the preference (e.g., 'Prefers dark mode in all apps').\"\n                },\n                \"category\": {\n                    \"type\": \"string\",\n                    \"is_required\": false,\n                    \"description\": \"The domain or class of the preference (e.g., 'UI', 'food', 'communication_style', 'programming_language'). Used to detect mutually exclusive preferences within the same category.\"\n                },\n                \"evidence_count\": {\n                    \"type\": \"number\",\n                    \"is_required\": false,\n                    \"description\": \"The number of independent Events or Experiences supporting this preference. Updated during consolidation. Epistemic support lives in metadata.confidence on the 'prefers' assertion link; retention and retrieval availability live separately in metadata.memory_strength. Reinforcement and time-based decay primarily update memory_strength, while confirming or contradicting evidence may update confidence.\"\n                },\n                \"first_observed\": {\n                    \"type\": \"string\",\n                    \"is_required\": false,\n                    \"description\": \"ISO 8601 timestamp of the earliest Event or Experience from which this preference was derived.\"\n                },\n                \"last_observed\": {\n                    \"type\": \"string\",\n                    \"is_required\": false,\n                    \"description\": \"ISO 8601 timestamp of the most recent Event or Experience confirming this preference.\"\n                },\n                \"source_event\": {\n                    \"type\": \"string\",\n                    \"is_required\": false,\n                    \"description\": \"Legacy convenience field containing the name of the original Event. New writes should use source_memory or the structural 'derived_from' proposition.\"\n                },\n                \"source_memory\": {\n                    \"type\": \"string\",\n                    \"is_required\": false,\n                    \"description\": \"Name of the original Event or Experience from which this preference was first derived. For multiple sources, use structural 'derived_from' propositions instead.\"\n                }\n            }\n        }\n        SET PROPOSITIONS {\n            (\"belongs_to_domain\", {type: \"Domain\", name: \"CoreSchema\"})\n        }\n    }\n\n    // Define the \"prefers\" predicate: Person → Preference\n    CONCEPT ?prefers_prop_def {\n        {type: \"$PropositionType\", name: \"prefers\"}\n        SET ATTRIBUTES {\n            description: \"Connects a Person to a graph-level `Preference` concept. Use this relation when the preference should participate in graph querying, provenance tracking, evidence aggregation, or temporal evolution. When a preference changes, the old proposition should be marked with superseded metadata rather than deleted.\",\n            object_types: [\"Preference\"],\n            subject_types: [\"Person\"]\n        }\n        SET PROPOSITIONS {\n            (\"belongs_to_domain\", {type: \"Domain\", name: \"CoreSchema\"})\n        }\n    }\n}\nWITH METADATA {\n    source: \"SystemBootstrap\",\n    author: \"$system\",\n    confidence: 1.0,\n    status: \"active\"\n}\n",
